// === Tab: mySketch ===
let asteroidBelt;
let numFrames = 50;

function setup() {
  createCanvas(windowWidth, windowHeight);
  asteroidBelt = new AsteroidBelt(
    windowWidth / 2,
    windowHeight / 2,
    150, 230, 500
  );
}

function draw() {
  background(26, 23, 24, 150);
  asteroidBelt.render();
}

class AsteroidBelt {
  constructor(x, y, minRadius, maxRadius, n) {
    this.x = x;
    this.y = y;
    this.minRadius = minRadius;
    this.maxRadius = maxRadius;
    this.n = n;

    this.asteroids = [];
    for (let i = 0; i < this.n; i++) {
      let t = random(0, 1);
      let distance = random(minRadius, maxRadius);
      let x = this.x + distance * cos(TWO_PI * t);
      let y = this.y + distance * sin(TWO_PI * t);
      let size = randomGaussian(6, 5);
      let speed = random(1, 5);
      this.asteroids[i] = new Asteroid(x, y, distance, size, speed, t);
    }
  }

  render() {
    for (let a of this.asteroids) {
      var t = a.t + 0.001 * a.speed;
      var distance = a.distance + a.d * sin(t * a.f);
      var x = this.x + distance * cos(TWO_PI * t);
      var y = this.y + distance * sin(TWO_PI * t);
      a.render(x, y, t);
    }
  }
}

class Asteroid {
  constructor(x, y, distance, size, speed, t) {
    this.x = x;
    this.y = y;
    this.distance = distance;
    this.size = size;
    this.speed = 5 / size;
    this.t = t;
    this.f = random(30, 60);
    this.d = random(5, 20);
    this.color = size < 2 ? color(255, 40, 40) : color(255);
  }

  render(x, y, t) {
    this.x = x;
    this.y = y;
    this.t = t;

    fill(this.color);
    stroke(this.color);
    ellipseMode(CENTER);
    ellipse(x, y, this.size, this.size);
  }
}

class Eye {
  constructor(x, y, size) {
    this.x = x;
    this.y = y;
    this.size = size;
  }

  render() {
    fill(0, 0);
    stroke(255, 100);
    ellipseMode(CENTER);
    // ellipse(this.x, this.y, this.size, this.size);

    let div = 240;
    let frameScale = (frameCount % div) / div;
    // ellipse(this.x, this.y, this.size, this.size * frameScale);

    for (let i = 0; i < 25; i++)
      ellipse(this.x, this.y,
        this.size * frameScale * i/5,
        this.size * frameScale * i/10);
  }
}

